public static int tambah(int a, int b) {
    return a + b;
}

public static void main(String[] args) {
    System.out.println(tambah(3, 5));
}

public static int faktorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * faktorial(n - 1);
}

public static void main(String[] args) {
    System.out.println(faktorial(4));
}
